"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[757],{780:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-04-linear-classification</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-4-линейная-классификация-логистическая-регрессия-метрики-и-svm">Лабораторная\nработа 4. Линейная классификация: логистическая регрессия, метрики и\nSVM</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 3</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 3: сигмоида (опр. 3.1), модель логистической регрессии (опр.\n3.2), логистическая потеря (опр. 3.3), градиент\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>h</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}(h-y)</annotation></semantics></math>\nи гессиан\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>S</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}SX</annotation></semantics></math>\n(утв. 3.4–3.6), отступ (опр. 3.8), прямая и двойственная задачи SVM\n(опр. 3.9, теорема 3.11), опорные векторы, мягкий зазор (опр. 3.14),\nядра (опр. 3.17); лекции 1–2: ERM, ММП, градиентный спуск</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно (части 1–3) + 6 ч самостоятельно</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Реализовать логистическую регрессию градиентным спуском и методом\nНьютона, опираясь на формулы градиента и гессиана из лекции 3; научиться\nизмерять качество классификации (матрица ошибок, precision/recall, ROC и\nPR-кривые) и понимать, какая метрика когда врёт; решить двойственную\nзадачу SVM численно, найти опорные векторы и увидеть, что классификатор\nзависит только от них; применить ядровой переход и сравнить ядра.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук <code>lab04_student.ipynb</code>, в котором:</p>\n<ol>\n<li>выполнены все задания (ячейки с <code># TODO</code>), код\nзапускается сверху вниз без ошибок;</li>\n<li>под каждым заданием заполнены ячейки <strong>Вывод</strong> — своими\nсловами, не пересказ кода;</li>\n<li>в конце — раздел «Итоги работы» с ответами на контрольные\nвопросы;</li>\n<li>все графики подписаны (заголовок, оси, легенда).</li>\n</ol>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже). Отчёт с чужим вариантом не\nпринимается.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> optimize</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> (load_breast_cancer, load_digits, load_wine,</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a>                              make_circles, make_moons)</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb1-50"><a href="#cb1-50" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb1-51"><a href="#cb1-51" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">4</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell markdown">\n<hr />\n<h1 id="часть-1-сигмоида-и-логистическая-потеря">Часть 1. Сигмоида и\nлогистическая потеря</h1>\n<p>Определение 3.1:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi><mo stretchy="false" form="prefix">(</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mstyle displaystyle="true"><mfrac><mn>1</mn><mrow><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mi>−</mi><mi>z</mi></mrow></msup></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">\\sigma(z) = \\dfrac{1}{1 + e^{-z}}</annotation></semantics></math>,\nи ключевое тождество\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>σ</mi><mo>′</mo></msup><mo stretchy="false" form="prefix">(</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>σ</mi><mo stretchy="false" form="prefix">(</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mn>1</mn><mo>−</mo><mi>σ</mi><mo stretchy="false" form="prefix">(</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\sigma&#39;(z) = \\sigma(z)\\bigl(1 - \\sigma(z)\\bigr)</annotation></semantics></math>\n— именно оно даёт красивую форму градиента в утверждении 3.4.</p>\n<p>Определение 3.3 (потеря,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">y \\in \\{0,1\\}</annotation></semantics></math>):\n<math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>θ</mi></msub><mo>,</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>−</mi><mi>y</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>g</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mrow><mi>ln</mi><mo>⁡</mo></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mn>1</mn><mo>−</mo><mi>g</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\mathcal L(a_\\theta, x, y) = -y\\ln g(x,\\theta) - (1-y)\\ln\\bigl(1 - g(x,\\theta)\\bigr).\n</annotation></semantics></math></p>\n<p>Если перейти к разметке\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mi>−</mi><mn>1</mn><mo>,</mo><mi>+</mi><mn>1</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">y \\in \\{-1,+1\\}</annotation></semantics></math>\nи ввести <strong>отступ</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo>=</mo><mi>y</mi><mspace width="0.167em"></mspace><msup><mi>θ</mi><mi>𝖳</mi></msup><mi>x</mi></mrow><annotation encoding="application/x-tex">M = y\\,\\theta^{\\mathsf T}x</annotation></semantics></math>,\nта же потеря записывается как\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>ln</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mi>−</mi><mi>M</mi></mrow></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\ln(1 + e^{-M})</annotation></semantics></math>.\nВ этой форме её удобно сравнивать с пороговой потерей\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">[</mo><mi>M</mi><mo>&lt;</mo><mn>0</mn><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">[M &lt; 0]</annotation></semantics></math>\nи с кусочно-линейной hinge-потерей\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>−</mo><mi>M</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\max(0, 1 - M)</annotation></semantics></math>,\nкоторая появится в части 6 (SVM).</p>\n</div>\n<div id="cell005" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> sigmoid(z):</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Численно устойчивая сигмоида (без переполнения при больших |z|).&quot;&quot;&quot;</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: для z &gt;= 0 считайте 1/(1+exp(-z)), для z &lt; 0 -- exp(z)/(1+exp(z))</span></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) проверьте тождество sigma&#39; = sigma (1 - sigma) численно (np.gradient);</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) убедитесь, что sigmoid(-1000) не даёт переполнения;</span></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) постройте два графика: сигмоида с производной и три потери</span></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a><span class="co">#          (пороговая, логистическая, hinge) как функции отступа M.</span></span></code></pre></div>\n</div>\n<div id="cell006" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Почему пороговую потерю\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">[</mo><mi>M</mi><mo>&lt;</mo><mn>0</mn><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">[M&lt;0]</annotation></semantics></math>\nне минимизируют напрямую? Какие два свойства логистической и\nhinge-потерь делают их пригодными для оптимизации?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell007" class="cell markdown">\n<hr />\n<h1 id="часть-2-своя-логистическая-регрессия">Часть 2. Своя\nлогистическая регрессия</h1>\n<p>Утверждение 3.4: для\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></msubsup><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>θ</mi></msub><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(\\theta) = \\sum_{i=1}^{\\ell}\\mathcal L(a_\\theta, x_i, y_i)</annotation></semantics></math></p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>θ</mi></msub><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>h</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mspace width="2.0em"></mspace><mi>h</mi><mo>=</mo><mi>σ</mi><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\nabla_\\theta Q(\\theta) = X^{\\mathsf T}(h - y), \\qquad h = \\sigma(X\\theta),\n</annotation></semantics></math></p>\n<p>а по утверждению 3.6 гессиан равен\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>∇</mi><mn>2</mn></msup><mi>Q</mi><mo>=</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>S</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">\\nabla^2 Q = X^{\\mathsf T}SX</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>S</mi><mo>=</mo><mrow><mi mathvariant="normal">d</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">g</mi></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><msub><mi>h</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><msub><mi>h</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">S = \\mathrm{diag}\\bigl(h_i(1-h_i)\\bigr)</annotation></semantics></math>.\nНаличие гессиана позволяет применить <strong>метод Ньютона</strong>:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo>+</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>=</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>−</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>S</mi><mi>X</mi><msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>h</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\theta^{(t+1)} = \\theta^{(t)} - \\bigl(X^{\\mathsf T}SX\\bigr)^{-1}X^{\\mathsf T}(h - y),\n</annotation></semantics></math></p>\n<p>известный в статистике как IRLS (iteratively reweighted least\nsquares).</p>\n<p>Реализуйте оба метода. <strong>Обязательно</strong> проверьте\nградиент численно приёмом из работы 2 — это ловит опечатку в формуле за\nминуту.</p>\n</div>\n<div id="cell008" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> logloss(theta, X, y, l2<span class="op">=</span><span class="fl">0.0</span>):</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Q(theta) = сумма логистических потерь + (l2/2)||theta_{1:}||^2.</span></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="co">    Подсказка: устойчиво считается как np.logaddexp(0, z) - y * z, где z = X @ theta.</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> logloss_grad(theta, X, y, l2<span class="op">=</span><span class="fl">0.0</span>):</span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Градиент X^T (h - y) по утверждению 3.4 (свободный член не регуляризуем).&quot;&quot;&quot;</span></span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-12"><a href="#cb4-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-13"><a href="#cb4-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-14"><a href="#cb4-14" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> logloss_hess(theta, X, y, l2<span class="op">=</span><span class="fl">0.0</span>):</span>\n<span id="cb4-15"><a href="#cb4-15" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Гессиан X^T S X по утверждению 3.6, S = diag(h_i (1 - h_i)).&quot;&quot;&quot;</span></span>\n<span id="cb4-16"><a href="#cb4-16" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-17"><a href="#cb4-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-18"><a href="#cb4-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-19"><a href="#cb4-19" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_logreg_gd(X, y, eta<span class="op">=</span><span class="va">None</span>, n_iter<span class="op">=</span><span class="dv">500</span>, l2<span class="op">=</span><span class="fl">0.0</span>):</span>\n<span id="cb4-20"><a href="#cb4-20" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Градиентный спуск. По умолчанию eta = 4/||X||_2^2 (константа Липшица).&quot;&quot;&quot;</span></span>\n<span id="cb4-21"><a href="#cb4-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-22"><a href="#cb4-22" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-23"><a href="#cb4-23" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-24"><a href="#cb4-24" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_logreg_newton(X, y, n_iter<span class="op">=</span><span class="dv">15</span>, l2<span class="op">=</span><span class="fl">1e-6</span>):</span>\n<span id="cb4-25"><a href="#cb4-25" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Метод Ньютона (IRLS): theta -= H^{-1} g.&quot;&quot;&quot;</span></span>\n<span id="cb4-26"><a href="#cb4-26" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-27"><a href="#cb4-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-28"><a href="#cb4-28" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-29"><a href="#cb4-29" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обязательно проверьте градиент И гессиан конечными разностями</span></span>\n<span id="cb4-30"><a href="#cb4-30" aria-hidden="true" tabindex="-1"></a><span class="co">#       (гессиан -- это якобиан градиента).</span></span></code></pre></div>\n</div>\n<div id="cell009" class="cell markdown">\n<h3 id="задание-22-данные-варианта-и-сравнение-со-sklearn">Задание 2.2.\nДанные варианта и сравнение со <code>sklearn</code></h3>\n<p>Загрузите датасет из <code>variant[&quot;dataset&quot;]</code>, при\nнеобходимости искусственно разбалансируйте классы согласно\n<code>variant[&quot;class_imbalance&quot;]</code>, отмасштабируйте признаки и\nобучите обе свои реализации. Сравните с\n<code>sklearn.linear_model.LogisticRegression</code> и постройте графики\nсходимости.</p>\n</div>\n<div id="cell010" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) загрузите датасет из variant[&quot;dataset&quot;]:</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a><span class="co">#          breast_cancer -&gt; load_breast_cancer()</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="co">#          wine          -&gt; load_wine(), метка = (target == 0)</span></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="co">#          digits        -&gt; load_digits(), только классы 3 и 8, метка = (target == 8)</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) примените искажение баланса из variant[&quot;class_imbalance&quot;]</span></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a><span class="co">#          (оставьте указанную долю объектов класса 1);</span></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) разбейте на train/test со стратификацией, отмасштабируйте,</span></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          добавьте столбец единиц;</span></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) обучите свои ГС и Ньютон (l2=1.0), сравните с</span></span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="co">#          LogisticRegression(C=1.0) -- сверьте и Q(theta), и сами коэффициенты;</span></span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a><span class="co">#       5) постройте график сходимости обоих методов (Q - Q* в лог. масштабе).</span></span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Сколько итераций потребовалось методу Ньютона\nи сколько — градиентному спуску? Почему разница такая большая и почему\nтогда метод Ньютона не используют всегда?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell012" class="cell markdown">\n<hr />\n<h1 id="часть-3-метрики-качества-классификации">Часть 3. Метрики\nкачества классификации</h1>\n<p>Матрица ошибок для порога\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>t</mi><annotation encoding="application/x-tex">t</annotation></semantics></math>:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>предсказано 0</th>\n<th>предсказано 1</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>истинно 0</strong></td>\n<td>TN</td>\n<td>FP</td>\n</tr>\n<tr>\n<td><strong>истинно 1</strong></td>\n<td>FN</td>\n<td>TP</td>\n</tr>\n</tbody>\n</table>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext mathvariant="normal">precision</mtext><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>P</mi></mrow></mfrac><mo>,</mo><mspace width="2.0em"></mspace><mtext mathvariant="normal">recall</mtext><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>N</mi></mrow></mfrac><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>F</mi><mn>1</mn></msub><mo>=</mo><mfrac><mrow><mn>2</mn><mspace width="0.167em"></mspace><mtext mathvariant="normal">PR</mtext></mrow><mrow><mtext mathvariant="normal">P</mtext><mo>+</mo><mtext mathvariant="normal">R</mtext></mrow></mfrac><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\text{precision} = \\frac{TP}{TP + FP}, \\qquad\n\\text{recall} = \\frac{TP}{TP + FN}, \\qquad\nF_1 = \\frac{2\\,\\text{PR}}{\\text{P} + \\text{R}},\n</annotation></semantics></math>\n<math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>P</mi><mi>R</mi><mo>=</mo><mtext mathvariant="normal">recall</mtext><mo>,</mo><mspace width="2.0em"></mspace><mi>F</mi><mi>P</mi><mi>R</mi><mo>=</mo><mfrac><mrow><mi>F</mi><mi>P</mi></mrow><mrow><mi>F</mi><mi>P</mi><mo>+</mo><mi>T</mi><mi>N</mi></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\nTPR = \\text{recall}, \\qquad FPR = \\frac{FP}{FP + TN}.\n</annotation></semantics></math></p>\n<p>ROC-кривая — множество точек\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mi>F</mi><mi>P</mi><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mi>T</mi><mi>P</mi><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(FPR(t), TPR(t))</annotation></semantics></math>\nпри всех порогах\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>t</mi><annotation encoding="application/x-tex">t</annotation></semantics></math>;\nAUC — площадь под ней. Полезная интерпретация: <strong>AUC равна\nвероятности того, что случайно взятый объект класса 1 получит больший\nбалл, чем случайно взятый объект класса 0.</strong></p>\n</div>\n<div id="cell013" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> confusion(y_true, y_pred):</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;[[TN, FP], [FN, TP]].&quot;&quot;&quot;</span></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> roc_curve_manual(y_true, score):</span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Точки ROC-кривой. Подсказка: отсортируйте по убыванию балла и возьмите</span></span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a><span class="co">    кумулятивные суммы меток -- это и есть TP(t) и FP(t).&quot;&quot;&quot;</span></span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> auc_manual(fpr, tpr):</span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Площадь под кривой методом трапеций.&quot;&quot;&quot;</span></span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-15"><a href="#cb6-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-16"><a href="#cb6-16" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-17"><a href="#cb6-17" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) сверьте свои confusion и AUC со sklearn;</span></span>\n<span id="cb6-18"><a href="#cb6-18" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) проверьте методом Монте-Карло интерпретацию AUC как вероятности</span></span>\n<span id="cb6-19"><a href="#cb6-19" aria-hidden="true" tabindex="-1"></a><span class="co">#          того, что случайный объект класса 1 получит больший балл, чем</span></span>\n<span id="cb6-20"><a href="#cb6-20" aria-hidden="true" tabindex="-1"></a><span class="co">#          случайный объект класса 0;</span></span>\n<span id="cb6-21"><a href="#cb6-21" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) постройте три графика: ROC-кривая, PR-кривая (с линией доли класса 1),</span></span>\n<span id="cb6-22"><a href="#cb6-22" aria-hidden="true" tabindex="-1"></a><span class="co">#          зависимость precision/recall/F1 от порога с отметкой оптимального порога.</span></span></code></pre></div>\n</div>\n<div id="cell014" class="cell markdown">\n<h3 id="задание-32-когда-accuracy-врёт">Задание 3.2. Когда accuracy\nврёт</h3>\n<p>Сравните четыре величины: accuracy константного классификатора\n«всегда 0», accuracy обученной модели, ROC-AUC и PR-AUC (average\nprecision) — при доле класса 1, меняющейся от 0.5 до 0.02.</p>\n<p>Чтобы эффект был виден в чистом виде, здесь берётся синтетическая\nвыборка <code>make_classification</code> с управляемой долей класса 1 и\nумеренной разделимостью (<code>class_sep=0.9</code>,\n<code>flip_y=0.02</code>): на «слишком лёгких» данных вроде digits\n3-vs-8 все метрики упираются в единицу и ничего не показывают.</p>\n</div>\n<div id="cell015" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> accuracy_score</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> make_classification</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: напишите функцию, которая по заданной доле класса 1 порождает выборку</span></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       make_classification(n_samples=4000, n_features=20, n_informative=5,</span></span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       n_redundant=3, class_sep=0.9, flip_y=0.02, weights=[1-frac, frac]),</span></span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       обучает LogisticRegression и возвращает accuracy «всегда 0»,</span></span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       accuracy модели, ROC-AUC и PR-AUC.</span></span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте таблицу и график этих метрик для долей</span></span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a><span class="co">#       [0.5, 0.35, 0.2, 0.1, 0.05, 0.03, 0.02].</span></span>\n<span id="cb7-12"><a href="#cb7-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;основная метрика вашего варианта:&quot;</span>, variant[<span class="st">&quot;main_metric&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell016" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая метрика перестаёт различать модель и\nконстанту при росте дисбаланса? Чем PR-AUC отличается от ROC-AUC в этой\nситуации и какую из них вы выберете для задачи поиска редкого события (1\n% положительных)?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell017" class="cell markdown">\n<hr />\n<h1 id="часть-4-линейно-разделимая-выборка-веса-уходят-в-бесконечность">Часть\n4. Линейно разделимая выборка: веса уходят в бесконечность</h1>\n<p>Если выборка линейно разделима, то у логистической потери <strong>нет\nминимума</strong>: для любого\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>θ</mi><annotation encoding="application/x-tex">\\theta</annotation></semantics></math>,\nразделяющего классы, увеличение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\theta\\|</annotation></semantics></math>\nв\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>c</mi><annotation encoding="application/x-tex">c</annotation></semantics></math>\nраз увеличивает все отступы в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>c</mi><annotation encoding="application/x-tex">c</annotation></semantics></math>\nраз и уменьшает\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(\\theta)</annotation></semantics></math>.\nФормально\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mrow><mi>inf</mi><mo>⁡</mo></mrow><mi>θ</mi></msub><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\inf_\\theta Q(\\theta) = 0</annotation></semantics></math>,\nно инфимум не достигается.</p>\n<p>Проверьте это: обучите модель без регуляризации на разделимых данных\nи следите за\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\theta\\|</annotation></semantics></math>.\nЗатем добавьте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>2</mn></msub><annotation encoding="application/x-tex">L_2</annotation></semantics></math>-штраф.</p>\n</div>\n<div id="cell018" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a>X_sep <span class="op">=</span> np.column_stack([np.ones(<span class="dv">60</span>), rng.normal(size<span class="op">=</span>(<span class="dv">60</span>, <span class="dv">2</span>))])</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>y_sep <span class="op">=</span> (X_sep[:, <span class="dv">1</span>] <span class="op">+</span> X_sep[:, <span class="dv">2</span>] <span class="op">&gt;</span> <span class="dv">0</span>).astype(<span class="bu">float</span>)      <span class="co"># заведомо разделимо</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите логрег градиентным спуском 20000 итераций при l2 = 0 и при l2 = 1,</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       записывая ||theta|| и Q каждые 100 итераций, и постройте два графика.</span></span></code></pre></div>\n</div>\n<div id="cell019" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Как ведёт себя\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\theta\\|</annotation></semantics></math>\nбез регуляризации и с ней? Что при этом происходит с предсказанными\nвероятностями и почему это плохо, даже если все ответы верны?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell020" class="cell markdown">\n<hr />\n<h1 id="часть-5-svm-двойственная-задача-и-опорные-векторы">Часть 5. SVM:\nдвойственная задача и опорные векторы</h1>\n<p>Теорема 3.11: двойственная задача SVM —</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><munder><mi>max</mi><mi>α</mi></munder><mspace width="0.222em"></mspace><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><msub><mi>α</mi><mi>i</mi></msub><mo>−</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><munder><mo>∑</mo><mrow><mi>i</mi><mo>,</mo><mi>j</mi></mrow></munder><msub><mi>α</mi><mi>i</mi></msub><msub><mi>α</mi><mi>j</mi></msub><msub><mi>y</mi><mi>i</mi></msub><msub><mi>y</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><msubsup><mi>x</mi><mi>i</mi><mi>𝖳</mi></msubsup><msub><mi>x</mi><mi>j</mi></msub><mo stretchy="false" form="postfix">)</mo><mspace width="1.0em"></mspace><mtext mathvariant="normal">при</mtext><mspace width="1.0em"></mspace><msub><mi>α</mi><mi>i</mi></msub><mo>≥</mo><mn>0</mn><mo>,</mo><mspace width="0.222em"></mspace><mspace width="0.222em"></mspace><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>α</mi><mi>i</mi></msub><msub><mi>y</mi><mi>i</mi></msub><mo>=</mo><mn>0</mn><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\max_{\\alpha}\\ \\sum_{i=1}^{\\ell}\\alpha_i\n- \\frac12\\sum_{i,j}\\alpha_i\\alpha_j y_i y_j (x_i^{\\mathsf T}x_j)\n\\quad\\text{при}\\quad \\alpha_i \\ge 0,\\ \\ \\sum_i \\alpha_i y_i = 0 ,\n</annotation></semantics></math></p>\n<p>и далее\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>w</mi><mo>*</mo></msup><mo>=</mo><msub><mo>∑</mo><mi>i</mi></msub><msubsup><mi>α</mi><mi>i</mi><mo>*</mo></msubsup><msub><mi>y</mi><mi>i</mi></msub><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">w^* = \\sum_i \\alpha_i^* y_i x_i</annotation></semantics></math>,\nа\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>b</mi><mo>*</mo></msup><annotation encoding="application/x-tex">b^*</annotation></semantics></math>\n— из любого объекта с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>α</mi><mi>i</mi><mo>*</mo></msubsup><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\alpha_i^* &gt; 0</annotation></semantics></math>:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>b</mi><mo>*</mo></msup><mo>=</mo><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msup><mi>w</mi><mrow><mi>*</mi><mi>𝖳</mi></mrow></msup><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">b^* = y_i - w^{*\\mathsf T}x_i</annotation></semantics></math>.\nОбъекты с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>α</mi><mi>i</mi><mo>*</mo></msubsup><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\alpha_i^* &gt; 0</annotation></semantics></math>\n— <strong>опорные векторы</strong>.</p>\n<p>Решите двойственную задачу способом из\n<code>variant[&quot;own_solver&quot;]</code> (в эталоне приведены все три) для\nлинейно разделимой выборки.</p>\n</div>\n<div id="cell021" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> solve_dual_slsqp(K, y, C<span class="op">=</span><span class="va">None</span>):</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Двойственная задача теоремы 3.11 через scipy.optimize.minimize (SLSQP).</span></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a><span class="co">    Минимизируется 0.5 a^T P a - sum(a), где P = (y y^T) * K,</span></span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a><span class="co">    при ограничениях 0 &lt;= a_i &lt;= C и a^T y = 0.</span></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> solve_dual_projgrad(K, y, C<span class="op">=</span><span class="va">None</span>, n_iter<span class="op">=</span><span class="dv">20_000</span>):</span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Проекционный градиентный подъём (см. подсказку в тексте).&quot;&quot;&quot;</span></span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-13"><a href="#cb9-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-14"><a href="#cb9-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-15"><a href="#cb9-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> solve_dual_smo(K, y, C<span class="op">=</span><span class="fl">1e6</span>, n_passes<span class="op">=</span><span class="dv">40</span>, tol<span class="op">=</span><span class="fl">1e-6</span>):</span>\n<span id="cb9-16"><a href="#cb9-16" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Упрощённый SMO: оптимизация пары множителей.&quot;&quot;&quot;</span></span>\n<span id="cb9-17"><a href="#cb9-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-18"><a href="#cb9-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-19"><a href="#cb9-19" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-20"><a href="#cb9-20" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> recover_wb(alpha, X, y, C<span class="op">=</span><span class="va">None</span>, tol<span class="op">=</span><span class="fl">1e-6</span>):</span>\n<span id="cb9-21"><a href="#cb9-21" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;w = sum a_i y_i x_i; b -- по объектам с 0 &lt; a_i (&lt; C).&quot;&quot;&quot;</span></span>\n<span id="cb9-22"><a href="#cb9-22" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-23"><a href="#cb9-23" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-24"><a href="#cb9-24" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-25"><a href="#cb9-25" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> make_blobs</span>\n<span id="cb9-26"><a href="#cb9-26" aria-hidden="true" tabindex="-1"></a>Xb, yb <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">60</span>, centers<span class="op">=</span><span class="dv">2</span>, cluster_std<span class="op">=</span><span class="fl">1.0</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb9-27"><a href="#cb9-27" aria-hidden="true" tabindex="-1"></a>yb <span class="op">=</span> np.where(yb <span class="op">==</span> <span class="dv">0</span>, <span class="op">-</span><span class="fl">1.0</span>, <span class="fl">1.0</span>)</span>\n<span id="cb9-28"><a href="#cb9-28" aria-hidden="true" tabindex="-1"></a>Xb <span class="op">=</span> StandardScaler().fit_transform(Xb) <span class="op">*</span> <span class="fl">1.2</span></span>\n<span id="cb9-29"><a href="#cb9-29" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-30"><a href="#cb9-30" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте решатель СВОЕГО варианта, решите двойственную задачу,</span></span>\n<span id="cb9-31"><a href="#cb9-31" aria-hidden="true" tabindex="-1"></a><span class="co">#       восстановите (w, b), посчитайте число опорных векторов и ширину полосы</span></span>\n<span id="cb9-32"><a href="#cb9-32" aria-hidden="true" tabindex="-1"></a><span class="co">#       2/||w||; сравните с SVC(kernel=&quot;linear&quot;, C=1e6).</span></span>\n<span id="cb9-33"><a href="#cb9-33" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;решатель вашего варианта:&quot;</span>, variant[<span class="st">&quot;own_solver&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell022" class="cell markdown">\n<h3 id="задание-52-картинка-полоса-и-опорные-векторы">Задание 5.2.\nКартинка: полоса и опорные векторы</h3>\n<p>Нарисуйте разделяющую гиперплоскость\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>w</mi><mi>𝖳</mi></msup><mi>x</mi><mo>+</mo><mi>b</mi><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">w^{\\mathsf T}x + b = 0</annotation></semantics></math>,\nграницы полосы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>w</mi><mi>𝖳</mi></msup><mi>x</mi><mo>+</mo><mi>b</mi><mo>=</mo><mi>±</mi><mn>1</mn></mrow><annotation encoding="application/x-tex">w^{\\mathsf T}x + b = \\pm 1</annotation></semantics></math>\nи выделите опорные векторы. Затем <strong>удалите из выборки все\nнеопорные объекты</strong>, переобучите SVM и убедитесь, что решение не\nизменилось.</p>\n</div>\n<div id="cell023" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) нарисуйте выборку, разделяющую прямую w^T x + b = 0, границы полосы</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="co">#          w^T x + b = +-1 и обведите опорные векторы;</span></span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) переобучите SVM ТОЛЬКО на опорных векторах и сравните (w, b)</span></span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a><span class="co">#          с решением на полной выборке.</span></span></code></pre></div>\n</div>\n<div id="cell024" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Сколько опорных векторов получилось и\nизменилось ли решение после удаления остальных объектов? Какое свойство\nдвойственной задачи это объясняет? Посмотрите на спектр множителей у\nитеративного решателя: почему там нет точных нулей и как это влияет на\nопределение опорного вектора?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell025" class="cell markdown">\n<hr />\n<h1 id="часть-6-мягкий-зазор-и-параметр-c">Часть 6. Мягкий зазор и\nпараметр\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math></h1>\n<p>Определение 3.14:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>min</mi><mo>⁡</mo></mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>C</mi><msub><mo>∑</mo><mi>i</mi></msub><msub><mi>ξ</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">\\min \\frac12\\|w\\|^2 + C\\sum_i\\xi_i</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><msub><mi>x</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi><mo stretchy="false" form="postfix">)</mo><mo>≥</mo><mn>1</mn><mo>−</mo><msub><mi>ξ</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">y_i(w^{\\mathsf T}x_i + b) \\ge 1 - \\xi_i</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>ξ</mi><mi>i</mi></msub><mo>≥</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\xi_i \\ge 0</annotation></semantics></math>.\nВ двойственной задаче добавляется ограничение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>α</mi><mi>i</mi></msub><mo>≤</mo><mi>C</mi></mrow><annotation encoding="application/x-tex">\\alpha_i \\le C</annotation></semantics></math>.</p>\n<p>Исключив\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>ξ</mi><mi>i</mi></msub><mo>=</mo><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><msub><mi>x</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\xi_i = \\max(0, 1 - y_i(w^{\\mathsf T}x_i + b))</annotation></semantics></math>,\nполучаем эквивалентную безусловную запись — <strong>регуляризованную\nминимизацию hinge-потери</strong>:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><munder><mi>min</mi><mrow><mi>w</mi><mo>,</mo><mi>b</mi></mrow></munder><mspace width="0.222em"></mspace><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>C</mi><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mrow><mi>max</mi><mo>⁡</mo></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mn>0</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>1</mn><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><msub><mi>x</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\min_{w,b}\\ \\frac12\\|w\\|^2 + C\\sum_{i=1}^{\\ell}\\max\\bigl(0,\\ 1 - y_i(w^{\\mathsf T}x_i + b)\\bigr).\n</annotation></semantics></math></p>\n<p>Сравните её с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>2</mn></msub><annotation encoding="application/x-tex">L_2</annotation></semantics></math>-регуляризованной\nлогистической регрессией из части 2: отличается только функция потерь\n(см. график из части 1).</p>\n</div>\n<div id="cell026" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a>Xm, ym <span class="op">=</span> make_moons(n_samples<span class="op">=</span><span class="dv">200</span>, noise<span class="op">=</span><span class="fl">0.28</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a>ym <span class="op">=</span> np.where(ym <span class="op">==</span> <span class="dv">0</span>, <span class="op">-</span><span class="fl">1.0</span>, <span class="fl">1.0</span>)</span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a>Xm <span class="op">=</span> StandardScaler().fit_transform(Xm)</span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: напишите функцию plot_decision(ax, predict, X, y, title), рисующую</span></span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       области решения и линии уровня decision_function = -1, 0, +1.</span></span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для C in [0.01, 0.1, 1, 100] обучите SVC(kernel=&quot;linear&quot;, C=C),</span></span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       нарисуйте границы и сведите в таблицу: число опорных векторов,</span></span>\n<span id="cb11-9"><a href="#cb11-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       ширину полосы 2/||w||, число ошибок на обучении.</span></span></code></pre></div>\n</div>\n<div id="cell027" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Как число опорных векторов и ширина полосы\nзависят от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>?\nКакому пределу соответствует\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>→</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">C \\to \\infty</annotation></semantics></math>,\nа какому —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">C \\to 0</annotation></semantics></math>?\nСопоставьте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nс параметром регуляризации\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>\nиз работы 3.</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell028" class="cell markdown">\n<hr />\n<h1 id="часть-7-ядра">Часть 7. Ядра</h1>\n<p>Определение 3.17:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">⟨</mo><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">⟩</mo></mrow><annotation encoding="application/x-tex">K(x,x&#39;) = \\langle\\varphi(x), \\varphi(x&#39;)\\rangle</annotation></semantics></math>.\nКритерий Мерсера:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>\n— ядро тогда и только тогда, когда матрица Грама\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>K</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>x</mi><mi>j</mi></msub><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|K(x_i,x_j)\\|</annotation></semantics></math>\nсимметрична и положительно полуопределена для любого набора точек.</p>\n<p>Проверьте три вещи:</p>\n<ol>\n<li><strong>Явное отображение.</strong> Для квадратичного ядра из\nпримера лекции\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msubsup><mi>x</mi><mn>1</mn><mn>2</mn></msubsup><mo>,</mo><msqrt><mn>2</mn></msqrt><mspace width="0.167em"></mspace><msub><mi>x</mi><mn>1</mn></msub><msub><mi>x</mi><mn>2</mn></msub><mo>,</mo><msubsup><mi>x</mi><mn>2</mn><mn>2</mn></msubsup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\varphi(x) = (x_1^2, \\sqrt2\\,x_1x_2, x_2^2)</annotation></semantics></math>\nубедитесь, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">⟨</mo><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">⟩</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>x</mi><mi>𝖳</mi></msup><msup><mi>x</mi><mo>′</mo></msup><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\langle\\varphi(x),\\varphi(x&#39;)\\rangle = (x^{\\mathsf T}x&#39;)^2</annotation></semantics></math>.</li>\n<li><strong>Критерий Мерсера.</strong> Посчитайте собственные числа\nматриц Грама для полиномиального и RBF-ядер — и для функции, ядром\n<strong>не</strong> являющейся (например,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>x</mi><mo>−</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">K(x,x&#39;) = \\|x - x&#39;\\|</annotation></semantics></math>).</li>\n<li><strong>Ядровой SVM.</strong> Решите двойственную задачу со своими\nядрами (<code>variant[&quot;kernels&quot;]</code>) на нелинейно разделимых\nданных.</li>\n</ol>\n</div>\n<div id="cell029" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> kernel_linear(A, B):</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> kernel_poly(A, B, d<span class="op">=</span><span class="dv">3</span>, c<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> kernel_rbf(A, B, gamma<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Подсказка: ||a-b||^2 = ||a||^2 - 2&lt;a,b&gt; + ||b||^2 (работа 1, часть 1).&quot;&quot;&quot;</span></span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb12-12"><a href="#cb12-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-13"><a href="#cb12-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-14"><a href="#cb12-14" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> kernel_sigmoid(A, B, gamma<span class="op">=</span><span class="fl">0.1</span>, c<span class="op">=</span><span class="fl">0.0</span>):</span>\n<span id="cb12-15"><a href="#cb12-15" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb12-16"><a href="#cb12-16" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-17"><a href="#cb12-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-18"><a href="#cb12-18" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (1) проверьте, что &lt;phi(x), phi(x&#39;)&gt; = (x^T x&#39;)^2 для</span></span>\n<span id="cb12-19"><a href="#cb12-19" aria-hidden="true" tabindex="-1"></a><span class="co">#           phi(x) = (x_1^2, sqrt(2) x_1 x_2, x_2^2);</span></span>\n<span id="cb12-20"><a href="#cb12-20" aria-hidden="true" tabindex="-1"></a><span class="co">#       (2) для 40 случайных точек посчитайте матрицы Грама всех четырёх ядер</span></span>\n<span id="cb12-21"><a href="#cb12-21" aria-hidden="true" tabindex="-1"></a><span class="co">#           и функции K(x,x&#39;) = ||x - x&#39;||; по знаку минимального собственного</span></span>\n<span id="cb12-22"><a href="#cb12-22" aria-hidden="true" tabindex="-1"></a><span class="co">#           числа определите, какие из них ядра (критерий Мерсера).</span></span></code></pre></div>\n</div>\n<div id="cell030" class="cell markdown">\n<h3 id="задание-72-ядровой-svm-своими-руками">Задание 7.2. Ядровой SVM\nсвоими руками</h3>\n<p>Соберите ядровой классификатор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi mathvariant="normal">s</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">g</mi><mi mathvariant="normal">n</mi></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><msub><mo>∑</mo><mi>i</mi></msub><msubsup><mi>α</mi><mi>i</mi><mo>*</mo></msubsup><msub><mi>y</mi><mi>i</mi></msub><mi>K</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>+</mo><msup><mi>b</mi><mo>*</mo></msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">a(x) = \\mathrm{sign}\\bigl(\\sum_i \\alpha_i^* y_i K(x_i, x) + b^*\\bigr)</annotation></semantics></math>\nна основе своего решателя двойственной задачи и сравните ядра из вашего\nварианта на выборках <code>make_moons</code> и\n<code>make_circles</code>.</p>\n</div>\n<div id="cell031" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="kw">class</span> KernelSVM:</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;SVM с произвольным ядром: обучение через двойственную задачу.</span></span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a><span class="co">    fit: решить двойственную задачу с матрицей K(X, X), запомнить alpha,</span></span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a><span class="co">         восстановить b по объектам с 0 &lt; alpha &lt; C.</span></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a><span class="co">    decision_function: sum_i alpha_i y_i K(x_i, x) + b.</span></span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сравните ядра из variant[&quot;kernels&quot;] на make_moons и make_circles:</span></span>\n<span id="cb13-12"><a href="#cb13-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       для каждой пары нарисуйте границу решения, выведите точность</span></span>\n<span id="cb13-13"><a href="#cb13-13" aria-hidden="true" tabindex="-1"></a><span class="co">#       и число опорных векторов.</span></span></code></pre></div>\n</div>\n<div id="cell032" class="cell markdown">\n<h3 id="задание-73-параметр-gamma-у-rbf-ядра">Задание 7.3. Параметр\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>\nу RBF-ядра</h3>\n<p><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi>exp</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mi>γ</mi><mo stretchy="false" form="postfix">∥</mo><mi>x</mi><mo>−</mo><msup><mi>x</mi><mo>′</mo></msup><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">K(x,x&#39;) = \\exp(-\\gamma\\|x-x&#39;\\|^2)</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>γ</mi><mo>=</mo><mn>1</mn><mi>/</mi><mo stretchy="false" form="prefix">(</mo><mn>2</mn><msup><mi>σ</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\gamma = 1/(2\\sigma^2)</annotation></semantics></math>.\nПостройте границы решения для\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>γ</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mn>0.01</mn><mo>,</mo><mn>0.1</mn><mo>,</mo><mn>1</mn><mo>,</mo><mn>10</mn><mo>,</mo><mn>100</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\gamma \\in \\{0.01, 0.1, 1, 10, 100\\}</annotation></semantics></math>\nи проследите за точностью на обучении и на контроле.</p>\n</div>\n<div id="cell033" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a>Xa, Xv, ya, yv <span class="op">=</span> train_test_split(Xm, ym, test_size<span class="op">=</span><span class="fl">0.4</span>, random_state<span class="op">=</span>RANDOM_STATE, stratify<span class="op">=</span>ym)</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для gamma in [0.01, 0.1, 1, 10, 100] обучите SVC(kernel=&quot;rbf&quot;),</span></span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       нарисуйте границы и сведите в таблицу точности на обучении и контроле</span></span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       и число опорных векторов.</span></span></code></pre></div>\n</div>\n<div id="cell034" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Что происходит с границей при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>γ</mi><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\gamma \\to 0</annotation></semantics></math>\nи при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>γ</mi><mo>→</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\gamma \\to \\infty</annotation></semantics></math>?\nНа каком\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>\nразрыв между обучением и контролем максимален и как это называется?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell035" class="cell markdown">\n<hr />\n<h1 id="часть-8-своя-выборка">Часть 8. Своя выборка</h1>\n<p>Сравните на индивидуальной выборке логистическую регрессию и SVM с\nядрами вашего варианта по основной метрике\n<code>variant[&quot;main_metric&quot;]</code>. Если ваш вариант — регрессионный,\nцелевую переменную бинаризуйте по медиане (и укажите это в отчёте).</p>\n</div>\n<div id="cell036" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> balanced_accuracy_score, f1_score</span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) если ваш вариант регрессионный -- бинаризуйте цель по медиане</span></span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a><span class="co">#          ОБУЧАЮЩЕЙ выборки (не всей!);</span></span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) обучите логистическую регрессию и SVM со всеми ядрами вашего варианта;</span></span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) сравните их по основной метрике variant[&quot;main_metric&quot;], по accuracy</span></span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          и по числу опорных векторов; добавьте строку с константным ответом.</span></span></code></pre></div>\n</div>\n<div id="cell037" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая модель победила по вашей основной\nметрике? Оправдало ли ядро усложнение по сравнению с линейной моделью?\nСколько объектов оказалось опорными и о чём это говорит?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell038" class="cell markdown">\n<h2 id="итоги-работы">Итоги работы</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Логистическая регрессия минимизирует\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mi>i</mi></msub><mrow><mi>ln</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mi>−</mi><msub><mi>M</mi><mi>i</mi></msub></mrow></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\sum_i \\ln(1+e^{-M_i})</annotation></semantics></math>,\nSVM —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>C</mi><msub><mo>∑</mo><mi>i</mi></msub><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>−</mo><msub><mi>M</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\frac12\\|w\\|^2 + C\\sum_i\\max(0, 1-M_i)</annotation></semantics></math>.\nНазовите два различия в поведении, которые следуют прямо из вида этих\nпотерь.</li>\n<li>Почему на линейно разделимой выборке у логистической регрессии без\nрегуляризации нет минимума, а у SVM с жёстким зазором — есть?</li>\n<li>У вас 1 000 000 объектов, из них 500 положительных. Модель даёт\naccuracy 0.9995 и ROC-AUC 0.97. Достаточно ли этого, чтобы внедрять\nмодель? Что ещё нужно посмотреть?</li>\n<li>Что такое опорный вектор и почему классификатор не меняется при\nудалении неопорных объектов? Сошлитесь на условие дополняющей\nнежёсткости.</li>\n<li>Ядро\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>x</mi><mo>−</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">K(x,x&#39;) = \\|x-x&#39;\\|</annotation></semantics></math>\nне удовлетворяет критерию Мерсера. Что конкретно сломается, если\nподставить его в двойственную задачу?</li>\n</ol>\n<h3 id="домашнее-задание">Домашнее задание</h3>\n<ol>\n<li><p><strong>Многоклассовое обобщение.</strong> Реализуйте схемы «один\nпротив всех» (one-vs-rest,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>M</mi><annotation encoding="application/x-tex">M</annotation></semantics></math>\nклассификаторов) и «каждый против каждого» (one-vs-one,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo stretchy="false" form="prefix">(</mo><mi>M</mi><mo>−</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo><mi>/</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">M(M-1)/2</annotation></semantics></math>\nклассификаторов) поверх своей бинарной логистической регрессии.\nПроверьте на <code>load_digits</code> (10 классов): сравните точность,\nвремя обучения и число обучаемых моделей. Покажите на рисунке область, в\nкоторой обе схемы дают неоднозначный ответ (для one-vs-rest — где\nнесколько классификаторов выдают +1). Сравните со <code>sklearn</code>\n(<code>multi_class=&#39;ovr&#39;</code> и <code>SVC</code> с\n<code>decision_function_shape</code>).</p></li>\n<li><p><strong>Полиномиальное ядро против RBF.</strong> Сгенерируйте\nвыборку, на которой полиномиальное ядро степени 2 <strong>строго\nлучше</strong> и линейного, и RBF при честном подборе\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>\nпо отложенной выборке (подсказка: класс задаётся квадратичной формой\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>x</mi><mi>𝖳</mi></msup><mi>A</mi><mi>x</mi><mo>≥</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">x^{\\mathsf T}Ax \\ge c</annotation></semantics></math>).\nПриведите таблицу качества и объясните, почему RBF проигрывает, хотя\nформально его пространство признаков бесконечномерно.</p></li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);